insert into public.site_lessons (sort, level, category, duration, title_en, title_th, desc_en, desc_th) values
  (10, 'beginner', 'groove', '14:52', 'Your First Beat, Done Right', 'จังหวะแรกของคุณ ที่ทำถูกตั้งแต่ต้น', 'Posture, grip and the eight-note groove — built so nothing has to be un-learned later.', 'ท่านั่ง การจับไม้ และกรูฟเขบ็ตหนึ่งชั้น วางให้ถูกตั้งแต่แรกจะได้ไม่ต้องมาแก้ทีหลัง'),
  (20, 'beginner', 'technique', '11:08', 'Single Stroke Roll Reset', 'รื้อ Single Stroke Roll ใหม่', 'Rebuild your singles with rebound instead of muscle. Ten minutes a day, six weeks.', 'สร้างซิงเกิลใหม่ด้วยแรงสะท้อนแทนการใช้กล้ามเนื้อ วันละสิบนาที หกสัปดาห์'),
  (30, 'beginner', 'reading', '16:30', 'Reading Rhythms: Quarter to Sixteenth', 'อ่านจังหวะ ตั้งแต่ตัวดำถึงเขบ็ตสองชั้น', 'Turn dots on a page into something your hands do without translating.', 'เปลี่ยนจุดบนกระดาษให้เป็นสิ่งที่มือทำได้เลยโดยไม่ต้องแปลในหัว'),
  (40, 'intermediate', 'groove', '18:24', 'The Linear Groove Blueprint', 'พิมพ์เขียวของ Linear Groove', 'Single-stream patterns that sound twice as busy as they actually are.', 'แพตเทิร์นเส้นเดียวที่ฟังดูแน่นเป็นสองเท่าของที่เล่นจริง'),
  (50, 'intermediate', 'technique', '12:40', 'Ghost Notes That Actually Speak', 'Ghost Note ที่ได้ยินจริง ๆ', 'Low-volume left hand control so ghosts survive the mix.', 'คุมมือซ้ายที่ความดังต่ำ ให้โน้ตผีรอดออกมาจากมิกซ์ได้'),
  (60, 'intermediate', 'technique', '21:15', 'Moeller Whip, Slowly', 'Moeller Whip แบบช้า ๆ', 'The full motion broken into four checkpoints you can actually feel.', 'แยกการเคลื่อนไหวทั้งชุดออกเป็นสี่จุดตรวจที่รู้สึกได้จริง'),
  (70, 'advanced', 'groove', '24:05', 'Odd Time Without the Panic', 'จังหวะขัดแบบไม่ต้องตกใจ', '5/4 and 7/8 using a grouping trick that makes counting unnecessary.', '5/4 และ 7/8 ด้วยทริกการจัดกลุ่มที่ทำให้ไม่ต้องนับ'),
  (80, 'advanced', 'reading', '19:47', 'Sight-Reading a Session Chart', 'อ่านชาร์ตงานจริงแบบสด', 'How to scan a chart in 30 seconds and survive the first take.', 'วิธีกวาดสายตาอ่านชาร์ตใน 30 วินาที แล้วรอดจากเทคแรก'),
  (90, 'advanced', 'groove', '27:12', 'Funk Independence Lab', 'ห้องแล็บอิสระแขนขาแนวฟังก์', 'Four-limb independence drilled against a real 16th-note funk track.', 'ฝึกอิสระสี่แขนขากับแทร็คฟังก์เขบ็ตสองชั้นจริง');
insert into public.site_packages (sort, name, sub_en, sub_th, price, price_was, save_en, save_th, is_best) values
  (10, '1 Lesson', 'Standard rate', 'ราคาปกติ', '1,000฿', '', '', '', false),
  (20, '8 Lessons', '5% off · 950฿ per lesson', 'ลด 5% · เฉลี่ย 950฿/คาบ', '7,600฿', '8,000฿', 'Save 400฿', 'ประหยัด 400฿', false),
  (30, '10 Lessons', '10% off · 900฿ per lesson', 'ลด 10% · เฉลี่ย 900฿/คาบ', '9,000฿', '10,000฿', 'Save 1,000฿', 'ประหยัด 1,000฿', true);
insert into public.site_faq (sort, q_en, q_th, a_en, a_th) values
  (10, 'Do I need my own drum kit?', 'ต้องมีกลองชุดเป็นของตัวเองไหม', 'No. The first two stages work completely on a practice pad, and every drill has a pad version. You will want a kit by the Independence stage, but a rehearsal room booking twice a week is enough.', 'ไม่จำเป็นครับ สองขั้นแรกฝึกบนแป้นซ้อมได้ทั้งหมด และทุกแบบฝึกหัดมีเวอร์ชันสำหรับแป้นซ้อม พอถึงขั้นอิสระของแขนขาถึงจะเริ่มต้องใช้กลองจริง แต่จองห้องซ้อมสัปดาห์ละสองครั้งก็เพียงพอ'),
  (20, 'Are the lessons in Thai or English?', 'บทเรียนเป็นภาษาไทยหรืออังกฤษ', 'Both. Every video carries Thai and English subtitles, and all sheet music and PDFs ship in both languages. Private coaching runs in whichever you prefer.', 'ทั้งสองภาษาครับ ทุกวิดีโอมีซับไตเติลทั้งไทยและอังกฤษ โน้ตเพลงและไฟล์ PDF ทั้งหมดก็มีสองภาษา ส่วนการเรียนส่วนตัวเลือกภาษาที่ถนัดได้เลย'),
  (30, 'How much should I practise?', 'ต้องซ้อมวันละเท่าไหร่', 'Twenty focused minutes a day beats three hours on Sunday. The practice plans are built around short daily blocks, and each one tells you exactly what to work on.', 'ซ้อมแบบมีสมาธิวันละยี่สิบนาที ดีกว่าซ้อมรวดสามชั่วโมงวันอาทิตย์ แผนการซ้อมออกแบบมาเป็นบล็อกสั้น ๆ ทุกวัน และแต่ละบล็อกบอกชัดเจนว่าต้องทำอะไร'),
  (40, 'Do lesson packages expire?', 'แพ็กเกจมีวันหมดอายุไหม', 'No. Once you buy an 8 or 10 lesson package the sessions stay yours — book them at whatever pace your schedule allows.', 'ไม่มีครับ ซื้อแพ็กเกจ 8 หรือ 10 คาบแล้วคาบเรียนเป็นของคุณ ทยอยนัดเรียนได้ตามตารางที่สะดวก'),
  (50, 'Do you take session work?', 'รับงานห้องอัดไหม', 'Yes — remote tracking and in-person sessions in Bangkok. Send the tempo, the reference and the deadline and I will quote you.', 'รับครับ ทั้งอัดส่งทางไกลและงานในกรุงเทพฯ ส่งเทมโป เพลงอ้างอิง และกำหนดส่งมา แล้วผมจะเสนอราคาให้');
insert into public.site_testimonials (sort, person, role_en, role_th, quote_en, quote_th) values
  (10, 'Nattapong S.', 'Church drummer, Chiang Mai', 'มือกลองโบสถ์ เชียงใหม่', 'Six weeks in and my timing finally stopped drifting during fills. The way the drills are sequenced makes the fix obvious.', 'เรียนได้หกสัปดาห์ จังหวะตอนตีฟิลล์ก็หยุดวืดสักที ลำดับแบบฝึกหัดทำให้เห็นชัดเลยว่าต้องแก้ตรงไหน'),
  (20, 'Marisa T.', 'Hobbyist, Bangkok', 'เล่นเป็นงานอดิเรก กรุงเทพฯ', 'I had been stuck at the same level for three years. The assessment put me exactly where I needed to be and the ceiling just disappeared.', 'ติดอยู่ที่ระดับเดิมมาสามปี พอทำแบบประเมินแล้วมันจัดที่ให้ตรงจุดพอดี เพดานที่เคยชนก็หายไปเลย'),
  (30, 'Daniel R.', 'Gigging drummer, Singapore', 'มือกลองอาชีพ สิงคโปร์', 'The video feedback alone is worth the package. It is like sitting next to him in the room.', 'แค่ฟีดแบ็กแบบวิดีโออย่างเดียวก็คุ้มค่าคอร์สแล้ว เหมือนเขานั่งอยู่ข้าง ๆ ในห้องซ้อมจริง ๆ');
insert into public.site_timeline (sort, year, title_en, title_th, desc_en, desc_th) values
  (10, '2006', 'Started on a second-hand five-piece', 'เริ่มจากกลองมือสองห้าใบ', 'Self-taught for three years on VHS tapes and a practice pad taped to a stool.', 'ฝึกเองอยู่สามปีจากม้วนวิดีโอกับแป้นซ้อมที่แปะไว้บนเก้าอี้'),
  (20, '2011', 'Formal study, jazz and percussion', 'เรียนแจ๊สและเพอร์คัชชันอย่างเป็นระบบ', 'Three years of reading, big band and the technique work that rebuilt my hands from scratch.', 'สามปีของการอ่านโน้ต เล่นบิ๊กแบนด์ และงานเทคนิคที่รื้อมือผมสร้างใหม่ทั้งหมด'),
  (30, '2014', 'First studio calls', 'งานอัดเสียงงานแรก', 'Tracking for pop and worship releases, learning to serve a song instead of showing off.', 'อัดให้งานป๊อปและงานนมัสการ ได้เรียนรู้ที่จะรับใช้เพลง ไม่ใช่โชว์ของ'),
  (40, '2017', 'Regional tours across Asia', 'ทัวร์ในภูมิภาคเอเชีย', 'Bangkok, Singapore, Taipei, Seoul — 120+ shows and a very tired ride cymbal.', 'กรุงเทพฯ สิงคโปร์ ไทเป โซล กว่า 120 โชว์ กับไรด์ฉาบหนึ่งใบที่เหนื่อยมาก'),
  (50, '2021', 'The Liang Method goes digital', 'Liang Method ขึ้นออนไลน์', 'Turned ten years of private lessons into a structured video curriculum.', 'เปลี่ยนบทเรียนตัวต่อตัวสิบปีให้เป็นหลักสูตรวิดีโอที่มีโครงสร้างชัดเจน');
insert into public.site_settings (key, label, value_en, value_th) values
  ('hero_eyebrow', 'หน้าแรก · บรรทัดบนสุด', 'Bangkok · Drum Educator & Session Player', 'กรุงเทพฯ · ครูสอนกลอง & มือกลองห้องอัด'),
  ('hero_role', 'หน้าแรก · บรรทัดตำแหน่ง', 'Drummer · Educator · Founder of the Liang Method', 'มือกลอง · ครูสอนกลอง · ผู้ก่อตั้ง Liang Method'),
  ('hero_text', 'หน้าแรก · ย่อหน้าแนะนำ', 'Twenty years behind the kit, distilled into a training system that turns loose hands into a locked, musical groove — online, at your own pace.', 'ประสบการณ์หลังกลองยี่สิบปี กลั่นออกมาเป็นระบบฝึกที่เปลี่ยนมือหลวม ๆ ให้กลายเป็นกรูฟที่นิ่งและมีดนตรี เรียนออนไลน์ได้ตามจังหวะของคุณเอง'),
  ('about_p1', 'หน้าแรก · แนะนำตัว ย่อหน้า 1', 'I am Suttipoj Liang W. — a session drummer and educator based in Bangkok. I have recorded for pop, funk and worship projects, toured across Asia, and spent the last decade teaching drummers who thought they had hit a ceiling.', 'ผมชื่อ ครูเลี้ยง (Suttipoj Liang W.) เป็นมือกลองห้องอัดและครูสอนกลองที่กรุงเทพฯ เคยอัดงานให้ทั้งเพลงป๊อป ฟังก์ และงานนมัสการ ออกทัวร์ทั่วเอเชีย และใช้เวลาสิบปีที่ผ่านมาสอนมือกลองที่คิดว่าตัวเองตันแล้ว'),
  ('about_p2', 'หน้าแรก · แนะนำตัว ย่อหน้า 2', 'What I teach is not a bag of tricks. It is a repeatable practice system — the same one that took me from a rented rehearsal room to studio calls.', 'สิ่งที่ผมสอนไม่ใช่กลเม็ดเป็นถุง แต่เป็นระบบการซ้อมที่ทำซ้ำได้ ระบบเดียวกับที่พาผมจากห้องซ้อมเช่าชั่วโมงละร้อย ไปจนถึงงานในห้องอัด'),
  ('profile_bio_1', 'ประวัติ · ย่อหน้า 1', 'I picked up a pair of sticks at eleven because a neighbour threw out a broken snare. Twenty years later the snare is still on my rack. Between those two points there were wedding gigs, worship teams, dep calls at two in the morning, three years of jazz studies, and more failed auditions than I like to count.', 'ผมจับไม้กลองครั้งแรกตอนอายุสิบเอ็ด เพราะเพื่อนบ้านทิ้งสแนร์ที่พังแล้วไว้หน้าบ้าน ยี่สิบปีต่อมาสแนร์ใบนั้นยังอยู่บนแร็คผม ระหว่างสองจุดนั้นมีทั้งงานแต่ง วงนมัสการ งานแทนตอนตีสอง เรียนแจ๊สอีกสามปี และออดิชั่นที่ตกมากกว่าที่อยากนับ'),
  ('profile_bio_2', 'ประวัติ · ย่อหน้า 2', 'That messy road is exactly why I teach the way I do. I know what it feels like to practise for hours and not get better, because I did it for years. The Liang Method exists so you do not have to repeat that.', 'เส้นทางที่ไม่สวยนั่นแหละคือเหตุผลที่ผมสอนแบบนี้ ผมรู้ดีว่าความรู้สึกซ้อมเป็นชั่วโมงแล้วไม่เก่งขึ้นมันเป็นยังไง เพราะผมเป็นแบบนั้นอยู่หลายปี Liang Method เกิดขึ้นมาเพื่อให้คุณไม่ต้องเดินซ้ำทางนั้น'),
  ('profile_bio_3', 'ประวัติ · ย่อหน้า 3', 'Today I split my time between studio sessions in Bangkok and teaching drummers online in fourteen countries.', 'ทุกวันนี้ผมแบ่งเวลาระหว่างงานห้องอัดในกรุงเทพฯ กับการสอนมือกลองออนไลน์ใน 14 ประเทศ'),
  ('promo_lead', 'บทเรียน · คำโปรยเหนือราคา', 'One-to-one lessons, paid per session. Buy a package and the per-lesson rate drops.', 'เรียนสดตัวต่อตัว คิดเป็นรายคาบ ซื้อเป็นแพ็กเกจยิ่งเฉลี่ยต่อคาบถูกลง'),
  ('promo_note', 'บทเรียน · หมายเหตุใต้ราคา', 'Prices are per lesson in Thai baht. Packages have no expiry — schedule at your own pace.', 'ราคาเป็นเงินบาทต่อคาบ แพ็กเกจไม่มีวันหมดอายุ นัดเรียนได้ตามจังหวะของคุณ'),
  ('contact_email', 'อีเมลติดต่อ', 'hello@suttipojdrums.com', 'hello@suttipojdrums.com'),
  ('contact_phone', 'เบอร์โทร', '+66 2 000 0000', '+66 2 000 0000'),
  ('contact_hours', 'เวลาทำการ', 'Mon – Sat, 10:00 – 20:00', 'จันทร์ – เสาร์ 10:00 – 20:00 น.'),
  ('contact_place', 'สถานที่', 'Bangkok, Thailand', 'กรุงเทพมหานคร ประเทศไทย')
